links = {  # 받는 서버: [(보내는 서버, 채널)]
    "dc1-01": [("dc2-01", "DR"), ("dc1-02", "MM")],
    "dc1-02": [("dc1-01", "MM")],
    "dc2-01": [("dc1-01", "DR"), ("dc2-02", "MM")],
    "dc2-02": [("dc2-01", "MM")],
}
sid = {"dc1-01": 101, "dc1-02": 102, "dc2-01": 1001, "dc2-02": 1002}

def run(ignore, hops=6):
    applied, queue = [], [("dc1-01", 101)]  # dc1-01 에서 생긴 변경 하나
    for _ in range(hops):
        nxt = []
        for at, origin in queue:
            for dst, srcs in links.items():
                for src, ch in srcs:
                    if src != at or origin == sid[dst]:
                        continue
                    if origin in ignore.get((dst, ch), set()):
                        continue
                    applied.append(dst); nxt.append((dst, origin))
        queue = nxt
    return applied

print("필터 없음:", run({}))
flt = {("dc2-01", "MM"): {101, 102}, ("dc1-01", "MM"): {1001, 1002},   # 원격 DC 것은 MM 으로 안 받는다
       ("dc2-01", "DR"): {1001, 1002}, ("dc1-01", "DR"): {101, 102}}   # 내 DC 것은 DR 로 안 받는다
print("필터 있음:", run(flt))

# 필터 없음: ['dc1-02', 'dc2-01', 'dc2-02', 'dc2-01', 'dc2-02', 'dc2-01', 'dc2-02']
# 필터 있음: ['dc1-02', 'dc2-01', 'dc2-02']
